<?php
namespace Copot\Core;
require_once __DIR__ . '/MediaUploadExceptions.php';
final class MediaUploadSource{private function __construct(private string $path,private string $originalFilename,private int $declaredSize,private string $browserMime){if($originalFilename===''||preg_match('//u',$originalFilename)!==1||preg_match('/[\x00-\x1F\x7F]/',$originalFilename))throw new MediaUploadValidationException('The uploaded filename is invalid.');if(strlen($originalFilename)>255||$declaredSize<=0||$path==='')throw new MediaUploadValidationException('The uploaded file is invalid.');}public static function fromArray(array $f):self{if(($f['error']??null)!==UPLOAD_ERR_OK||!is_string($f['tmp_name']??null)||!is_string($f['name']??null)||!is_int($f['size']??null))throw new MediaUploadValidationException('The uploaded file is invalid.');$n=trim($f['name']);if(class_exists('Normalizer'))$n=\Normalizer::normalize($n,\Normalizer::FORM_C)?:$n;return new self($f['tmp_name'],$n,$f['size'],is_string($f['type']??null)?$f['type']:'');}public function path():string{return $this->path;}public function originalFilename():string{return $this->originalFilename;}public function declaredSize():int{return $this->declaredSize;}public function browserMime():string{return $this->browserMime;}}
